effect.shader:
// Advanced CC Filters - Hand-crafted cinematic looks

vec3 saturateCol(vec3 col, float sat) {
    float grey = dot(col, vec3(0.2126, 0.7152, 0.0722));
    return mix(vec3(grey), col, sat);
}

vec3 applyContrast(vec3 col, float con) {
    return (col - 0.5) * con + 0.5;
}

// --- Procedural Textures ---
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

float noise(vec2 p) {
    vec2 i = floor(p); vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + vec2(1,0)), f.x),
               mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);
}

float getGrain(vec2 uv, float t) {
    return hash(uv + t);
}

float getScratches(vec2 uv, float t) {
    float x = uv.x * 200.0;
    float r = hash(vec2(floor(x), floor(t * 10.0)));
    if (r > 0.99) return smoothstep(0.1, 0.0, abs(fract(x) - 0.5));
    return 0.0;
}

float getDust(vec2 uv, float t) {
    vec2 p = uv * 50.0;
    float n = noise(p + t * 5.0);
    return step(0.98, n) * hash(uv + t);
}

vec3 getLightLeaks(vec2 uv, float t) {
    vec2 p = uv + vec2(t * 0.1, sin(t * 0.5) * 0.2);
    float n = noise(p * 2.0);
    vec3 c1 = vec4(1.0, 0.4, 0.2, 1.0).rgb * smoothstep(0.4, 0.8, n);
    vec3 c2 = vec4(0.2, 0.4, 1.0, 1.0).rgb * smoothstep(0.4, 0.8, noise(p * 3.0 + 10.0));
    return (c1 + c2) * 0.5;
}

vec3 applyBloom(vec3 col, float str) {
    float luma = dot(col, vec3(0.2126, 0.7152, 0.0722));
    vec3 highlight = col * smoothstep(0.6, 1.0, luma);
    return col + highlight * str * 2.0;
}

vec3 applyVignette(vec3 col, vec2 uv, float str) {
    float d = distance(uv, vec2(0.5));
    return col * smoothstep(0.8, 0.4 + (1.0 - str) * 0.4, d);
}

vec3 getGlitch(vec2 uv, float t, float str) {
    vec2 gUv = uv;
    float gNoise = hash(vec2(floor(t * 10.0), floor(uv.y * 10.0)));
    if (gNoise > 0.98) gUv.x += (hash(vec2(t)) - 0.5) * 0.05 * str;
    return texture2DCv(inputImg.texture, gUv).rgb;
}

float getLensDirt(vec2 uv, float t) {
    float dirt = noise(uv * 10.0 + t * 0.05);
    return smoothstep(0.7, 1.0, dirt) * 0.1;
}

vec3 applyLetterbox(vec3 col, vec2 uv, float str) {
    float mask = step(0.1 * str, uv.y) * step(uv.y, 1.0 - 0.1 * str);
    return col * mask;
}

float getStatic(vec2 uv, float t) {
    return hash(uv + t * 20.0);
}

void main() {
    vec2 uv = acScreenNorm;
    float t = acTime;

    // Chromatic Aberration (RGB Split)
    float ca = vhsMode * 0.005;
    vec4 srcR = texture2DCv(inputImg.texture, uv + vec2(ca, 0));
    vec4 srcG = texture2DCv(inputImg.texture, uv);
    vec4 srcB = texture2DCv(inputImg.texture, uv - vec2(ca, 0));
    vec3 col = vec3(srcR.r, srcG.g, srcB.b);
    float alpha = srcG.a;

    // VHS Jitter/Tracking
    if (vhsMode > 0.1) {
        float jitter = (hash(vec2(t, uv.y)) - 0.5) * 0.01 * vhsMode;
        if (hash(vec2(t * 0.5)) > 0.98) uv.x += jitter;
        col = texture2DCv(inputImg.texture, uv).rgb;
    }

    // --- Filter Algorithms ---
    vec3 filterCol = col;

    if (filterMode == 0) { // Teal & Orange
        float luma = dot(col, vec3(0.2126, 0.7152, 0.0722));
        filterCol.r = pow(col.r, 0.8) * 1.25;
        filterCol.g = col.g;
        filterCol.b = pow(col.b, 1.2) * 0.85;
        filterCol = mix(filterCol, vec3(luma * 1.5, luma * 1.0, luma * 0.8), 0.15); // Tint
    } 
    else if (filterMode == 1) { // Moody Blue
        filterCol = col * vec3(0.8, 0.9, 1.1);
        filterCol = applyContrast(filterCol, 1.2);
        filterCol = mix(filterCol, vec3(dot(filterCol, vec3(0.3, 0.59, 0.11))), 0.2); // Desaturate
    }
    else if (filterMode == 2) { // Autumn Gold
        filterCol = col * vec3(1.15, 0.95, 0.8);
        filterCol.r = smoothstep(0.0, 1.0, filterCol.r * 1.1);
        filterCol.b = pow(filterCol.b, 1.3);
    }
    else if (filterMode == 3) { // Bleach Bypass
        float luma = dot(col, vec3(0.2126, 0.7152, 0.0722));
        vec3 overlay = (luma < 0.5) ? (2.0 * col * luma) : (1.0 - 2.0 * (1.0 - col) * (1.0 - luma));
        filterCol = mix(col, overlay, 0.6);
        filterCol = saturateCol(filterCol, 0.4);
    }
    else if (filterMode == 4) { // Urban Cyber
        filterCol = col * vec3(1.1, 0.8, 1.2); // Magenta tint
        filterCol.r = pow(filterCol.r, 0.9);
        filterCol.b = pow(filterCol.b, 0.85);
        filterCol = applyContrast(filterCol, 1.1);
    }
    else if (filterMode == 5) { // Vintage 70s
        filterCol = col * vec3(1.1, 1.05, 0.85);
        filterCol = mix(filterCol, vec3(0.2, 0.15, 0.1), 0.1); // Faded blacks
        filterCol = saturateCol(filterCol, 0.8);
    }
    else if (filterMode == 6) { // Cold Winter
        filterCol = col * vec3(0.9, 1.1, 1.25);
        filterCol += 0.05; // Brighten
        filterCol = applyContrast(filterCol, 0.95);
    }
    else if (filterMode == 7) { // Pastel Soft
        filterCol = pow(col, vec3(0.8)); // Gamma up
        filterCol = saturateCol(filterCol, 1.1);
        filterCol = mix(filterCol, vec3(1.0), 0.1); // Fog/Milk
    }
    else if (filterMode == 8) { // Dramatic B&W
        float luma = dot(col, vec3(0.2126, 0.7152, 0.0722));
        filterCol = vec3(pow(luma, 1.4) * 1.2);
        filterCol = applyContrast(filterCol, 1.3);
    }
    else if (filterMode == 9) { // Noir
        float luma = dot(col, vec3(0.299, 0.587, 0.114));
        filterCol = vec3(smoothstep(0.1, 0.9, luma));
        filterCol *= 0.9; // Lower max whites
    }
    else if (filterMode == 10) { // Sunset Glow
        filterCol = col * vec3(1.3, 0.9, 0.7);
        filterCol.g = pow(filterCol.g, 1.1);
        filterCol.b = pow(filterCol.b, 1.4);
    }
    else if (filterMode == 11) { // Deep Forest
        filterCol = col * vec3(0.9, 1.15, 0.95);
        filterCol.rb = pow(filterCol.rb, vec2(1.2));
        filterCol = mix(filterCol, vec3(0.0, 0.1, 0.05), 0.1);
    }
    else if (filterMode == 12) { // Polaroid
        filterCol = col * vec3(1.0, 1.0, 0.9);
        filterCol = applyContrast(filterCol, 1.15);
        filterCol = mix(filterCol, vec3(0.1, 0.1, 0.2), 0.1); // Blue shadows
        filterCol = saturateCol(filterCol, 0.9);
    }
    else if (filterMode == 13) { // Infrared
        float luma = dot(col, vec3(0.21, 0.72, 0.07));
        filterCol = vec3(luma * 1.2, luma * 0.5, luma * 0.9);
        filterCol.r = smoothstep(0.1, 0.9, filterCol.r);
    }
    else if (filterMode == 14) { // Kodak Gold
        filterCol = col * vec3(1.1, 1.0, 0.8);
        filterCol = saturateCol(filterCol, 1.25);
        filterCol = applyContrast(filterCol, 1.1);
    }
    else if (filterMode == 15) { // Night Vision
        float luma = dot(col, vec3(0.21, 0.72, 0.07));
        filterCol = vec3(luma * 0.2, luma * 1.5, luma * 0.2);
    }
    else if (filterMode == 16) { // Sepia Modern
        float luma = dot(col, vec3(0.21, 0.72, 0.07));
        filterCol = vec3(luma) * vec3(1.2, 1.0, 0.8);
        filterCol = applyContrast(filterCol, 1.1);
    }
    else if (filterMode == 17) { // Technicolor
        filterCol = pow(col, vec3(0.8));
        filterCol = saturateCol(filterCol, 1.5);
        filterCol = applyContrast(filterCol, 1.2);
    }
    else if (filterMode == 18) { // Hollywood Gold
        filterCol = col * vec3(1.15, 1.05, 0.9);
        filterCol = mix(filterCol, vec3(1.0, 0.8, 0.5), 0.05);
    }
    else if (filterMode == 19) { // Lomo
        filterCol = applyContrast(col, 1.3);
        filterCol.r = pow(filterCol.r, 0.9);
        float luma = dot(col, vec3(0.299, 0.587, 0.114));
        filterCol = vec3(smoothstep(0.1, 0.9, luma));
        filterCol *= 0.9;
    }
    else if (filterMode == 20) { // 8mm Film
        filterCol = col * vec3(1.1, 0.95, 0.8);
        filterCol = applyContrast(filterCol, 1.2);
        filterCol += getLightLeaks(uv, t) * 0.3;
    }
    else if (filterMode == 21) { // Bleach Bypass II
        float luma = dot(col, vec3(0.2126, 0.7152, 0.0722));
        filterCol = mix(col, vec3(luma), 0.7);
        filterCol = applyContrast(filterCol, 1.5);
    }
    else if (filterMode == 22) { // Cool Night Shift
        filterCol = col * vec3(0.7, 0.85, 1.2);
        filterCol.r = pow(filterCol.r, 1.3);
    }
    else if (filterMode == 23) { // Warm Retro
        filterCol = col * vec3(1.2, 1.1, 0.9);
        filterCol = mix(filterCol, vec3(1.0, 0.9, 0.7), 0.1);
    }
    else if (filterMode == 24) { // Cyberpunk Red
        filterCol = col * vec3(1.4, 0.5, 1.2);
        filterCol = applyContrast(filterCol, 1.2);
    }
    else if (filterMode == 25) { // Matrix
        filterCol = col * vec3(0.5, 1.4, 0.5);
        filterCol = applyContrast(filterCol, 1.3);
    }
    else if (filterMode == 26) { // Washed Out
        filterCol = col * 0.8 + 0.2;
        filterCol = saturateCol(filterCol, 0.6);
    }
    else if (filterMode == 27) { // High Key
        filterCol = pow(col, vec3(0.7)) * 1.1;
        filterCol = saturateCol(filterCol, 0.8);
    }
    else if (filterMode == 28) { // Low Key
        filterCol = pow(col, vec3(1.8));
        filterCol = applyContrast(filterCol, 1.1);
    }
    else if (filterMode == 29) { // Dreamy Mist
        filterCol = applyBloom(col, 0.5);
        filterCol = saturateCol(filterCol, 1.1);
    }

    // --- Apply Overlays ---
    float grain = getGrain(uv, t) * 0.15;
    float scratches = getScratches(uv, t) * 0.5;
    float dust = getDust(uv, t) * 0.8;
    float scanline = sin(uv.y * 800.0) * 0.04;
    vec3 leaks = getLightLeaks(uv, t) * 0.6;

    // Master Overlay Integration
    if (overlayStrength > 0.01) {
        // Mapping by Filter Personality - ALL 30 Filters covered
        bool isVintage = (filterMode == 5 || filterMode == 12 || filterMode == 14 || filterMode == 16 || filterMode == 17 || filterMode == 19 || filterMode == 20 || filterMode == 23 || filterMode == 26);
        bool isDigital = (filterMode == 4 || filterMode == 13 || filterMode == 15 || filterMode == 24 || filterMode == 25);
        bool isBright = (filterMode == 2 || filterMode == 6 || filterMode == 7 || filterMode == 10 || filterMode == 27 || filterMode == 29);
        bool isCinematic = (filterMode == 0 || filterMode == 1 || filterMode == 3 || filterMode == 8 || filterMode == 9 || filterMode == 11 || filterMode == 18 || filterMode == 21 || filterMode == 22 || filterMode == 28);

        if (isVintage) {
            filterCol += (grain + scratches + dust) * overlayStrength;
            filterCol += leaks * overlayStrength * 0.5;
            filterCol *= 1.0 + (sin(t * 12.0) * 0.02 * overlayStrength); // Flicker
        }
        if (isDigital) {
            filterCol -= scanline * overlayStrength;
            filterCol += getStatic(uv, t) * 0.05 * overlayStrength;
            if (hash(vec2(t)) > 0.98) filterCol = getGlitch(uv, t, overlayStrength);
        }
        if (isBright) {
            filterCol += getLensDirt(uv, t) * overlayStrength;
            filterCol += leaks * 0.3 * overlayStrength;
            filterCol = applyBloom(filterCol, 0.2 * overlayStrength);
        }
        if (isCinematic) {
            filterCol = applyVignette(filterCol, uv, 0.6 * overlayStrength);
            filterCol = applyLetterbox(filterCol, uv, 0.5 * overlayStrength);
            filterCol += grain * 0.1 * overlayStrength;
        }
    }

    // Apply intensity
    col = mix(col, filterCol, intensity);

    // --- Global Adjustments ---
    col += brightness;
    col = applyContrast(col, contrast);
    col = saturateCol(col, saturation);

    // Pro Overlays
    col = applyBloom(col, bloomStrength);
    col = applyVignette(col, uv, vignette);

    gl_FragColor = vec4(col, alpha) * blend + (1.0 - blend) * srcG;
}
